changeSet.sql:
-- Remove DAA associations - these are not in use yet and cause FK problems DELETE FROM lc_daa;
-- Remove duplicate library cards based on user_id DELETE FROM library_card WHERE id IN (SELECT id FROM (SELECT id, ROW_NUMBER() OVER( PARTITION BY user_id ORDER BY id ) AS row_num FROM library_card) t WHERE t.row_num > 1);
-- Remove duplicate library cards based on user_email where user_id is null DELETE FROM library_card WHERE id IN (SELECT id FROM (SELECT id, ROW_NUMBER() OVER( PARTITION BY user_email ORDER BY id ) AS row_num FROM library_card WHERE user_id IS NULL) t WHERE t.row_num > 1);
